  addMesh(body, GEO.box, apron, [0, 0.02, 0.2], [0, 0, 0], [0.34, 0.62, 0.04]);
  addMesh(body, GEO.box, gold, [0, -0.28, 0.23], [0, 0, 0], [0.35, 0.05, 0.03]);
