  addMesh(head, GEO.sphereLow, hair, [0, 0.18, -0.12], [0, 0, 0], [0.1, 0.09, 0.1]);
  addMesh(head, GEO.sphereLow, mat('#2a1a12'), [-0.055, 0.02, 0.145], [0, 0, 0], [0.018, 0.022, 0.012]);
  addMesh(head, GEO.sphereLow, mat('#2a1a12'), [0.055, 0.02, 0.145], [0, 0, 0], [0.018, 0.022, 0.012]);
