  addMesh(g, SHARED.box, mat('#a58145'), [0.2, 1.62, 0.95], [0, 0.3, 0], [0.55, 0.32, 0.35]);
  addMesh(g, SHARED.sphere, mat('#b85d3e'), [1.1, 1.65, 0.92], [0, 0, 0], [0.16, 0.14, 0.16]);
