  addMesh(g, SHARED.cone, mat(color, { side: THREE.DoubleSide }), [0.35, 1.75, 0], [Math.PI, 0, 0], [0.35, 0.4, 0.02]);
  addMesh(g, SHARED.sphere, mat('#d4b56c', { metalness: 0.6 }), [0, 3.5, 0], [0, 0, 0], [0.09, 0.09, 0.09]);
