content.text:
Wait first edit replaced in updateProfileUI; second in updateVitals. Good. Need also update shop render count maybe fine.

Now main.js. Let's write carefully.

Pseudo:

```
import './styles.css';
import * as THREE from 'three';
...
const app = {...};

async function init() {
  const ui = new GameUI(); app.ui=ui;
  bindUI();
  app.audio = new AudioEngine();
  app.input = new Input(); bindInput();
  app.profile = loadProfile();
  ui.setProfile(app.profile);
  ui.setSoundIcon(app.audio.muted);
  ui.buildClassCards(CLASSES, app.profile.selectedClass);
  ui.updateSelectPanel(app.profile.selectedClass, app.profile);
  window.addEventListener('resize', onResize);
  window.addEventListener('beforeunload', ()=>saveProfile(app.profile));
  initHitFlash();
  try {
    const art = await generateArt();
    ui.setPortraits(art.portraits);
    ui.setMapThumbs(art.thumbs);
    ui.buildClassCards(CLASSES, app.profile.selectedClass);
    ui.updateSelectPanel(app.profile.selectedClass, app.profile);
  } catch(e) { console.error(e); }
  setupRenderer();
  enterTitle();
  ui.showBootProgress(100);
  ui.hideBoot();
  requestAnimationFrame(loop);
}
```

But `setupRenderer` before generateArt? The offscreen renderer generation uses its own; okay after. But boot screen progress uses DOM. Fine.

Maybe generateArt needs renderer settings; use own.

BindUI:
```
ui.handlers = {
 onStart: () => { audio.init(); audio.play('ui'); enterSelect(); },
 onBackTitle: ...
 onSelectClass: selectClass,
 onConfirmClass: (id)=>{...},
 onOpenShop: openShop,
 onOpenMaps: openMaps,
 onCloseModal: closeModal,
 onEnterMap: (id)=>startAdventure(id),
 onLobby: goLobby,
 onPause: togglePause,
 onResume: resume,
 onPauseLobby: goLobby,
 onRetry: retry,
 onResultLobby: goLobby,
 onOpenHelp: openHelp,
 onCloseHelp: closeHelp,
 onBuy: buy,
 onEquip: equip,
 onSound: toggleSound,
};
```
- `onStart` maybe if profile exists and completed? still select. Fine.
- On confirm class, maybe show toast in lobby "Bem-vindo..."? We'll do.
- `onCloseModal('shop'|'maps')` -> closeModal; app.uiPaused=false.
- `onEnterMap` from map modal: close modal, start adventure.
- `onLobby` if state adventure -> goLobby; if state lobby -> maybe toast "Você já está no lobby". Button only adventure.
- `onPause` toggles.

BindInput:
```
input.on('ability', castAbility)
input.on('dodge', doDodge)
input.on('potion', usePotion)
input.on('pause', handleEscape)
input.on('lobby', goLobby)
input.on('uiClick', ()=> audio.init())
```
- attack: don't bind; use held/queued.
- Add global pointerdown/keydown to init audio.
- `input.enabled` always true; movement skipped when modal.

Global first gesture:
```
const startAudio=()=>{ audio.init(); audio.setMood(moodForState()); };
window.addEventListener('pointerdown', startAudio, {once:true});
window.addEventListener('keydown', startAudio, {once:true});
```
But when audio.init called in onStart too. Fine. Mood set after init. `moodForState()`.

`generateArt`:
```
async function generateArt() {
  const renderer = new THREE.WebGLRenderer({antialias:true, alpha:true, preserveDrawingBuffer:true, powerPreference:'high-performance'});
  renderer.setPixelRatio(1);
  renderer.outputColorSpace=SRGBColorSpace;
  renderer.toneMapping=ACESFilmicToneMapping;
  renderer.toneMappingExposure=1.15;
  renderer.setClearColor(0x000000,0);
  const classes={};
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(34, 360/480, .1, 20);
  ... lights
  renderer.setSize(360,480);
  for each class:
    const hero=createHero(c.id); hero.position.y=0; hero.rotation.y=-0.35; scene.add;
    animateHero(hero, 0.7,{moving:0});
    renderer.render(scene,camera);
    classes[c.id]=renderer.domElement.toDataURL('image/png');
    scene.remove(hero);
    ui.showBootProgress(8 + i*9);
    await nextFrame();
  // vendor
  scene.clear? remove all; create new scene
  ...
  renderer.setSize(420,420); camera aspect=1; camera.position...
  vendor/dog...
  renderer.render; vendor=...
  // thumbs
  renderer.setSize(480,300);
  for maps:
    const d=buildMapDiorama(map.id); d.camera.aspect=1.6; d.camera.updateProjectionMatrix(); renderer.render; thumbs...
  renderer.dispose(); renderer.forceContextLoss();
  return {portraits:{classes,vendor},thumbs};
}
```
- When rendering transparent portraits, scene.background=null; renderer.setClearColor(0,0). Good.
- Lights for portrait: ambient/hemi, key directional at (3,5,4), rim point class color at (-2,2,-2), fill point.
- Need camera lookAt (0,1.02,0), position (0,1.2,3.5). For tall warden helmet 2.0, fov 34 height visible 2.15 at 3.5? 2*3.5*tan(17°)=2.14, good. Feet at 0, head at ~2.0, lookAt 1.05 => visible from -0.02 to 2.12. Good.
- For sorceress hat extends to ~2.2; camera lookAt 1.1 maybe cut. Set camera position (0,1.25,3.9), fov 36 => height 2.54. Good. Use fov 36, dist 3.9, lookAt 1.08.
- Portrait width 360, height 480 aspect .75, vertical fov 36 => horizontal smaller; fine.
- For vendor portrait, camera fov 36, position (0,1.3,4.6), lookAt (0,1.0,0), size 420x420 aspect 1. Vendor height 2.1, dog 1.0. Good.
- Thumbnail diorama camera aspect set 1.6; diorama camera position set; fine.

`nextFrame`:
```
const nextFrame = () => new Promise(r=>requestAnimationFrame(()=>setTimeout(r,0)));
```
In init, `await nextFrame()`.

`setupRenderer`:
- create renderer using existing canvas.
- set size.
- `app.renderer`.
- `initHitFlash`.

`enterTitle`:
- Build title if not.
- app.scene=...
- app.camera=...
- ui.showTitle
- audio mood.
