`updateLobby(dt)`:
```
const world=app.lobbyWorld;
world.update(time,dt);
const overlay=isOverlayOpen();
let moving=0;
if(!overlay){
 const move=input.getMove();
 if(move.magnitude>0.05){
   const len=Math.hypot(move.x,move.y); const dx=move.x/len, dz=move.y/len;
   const spd=app.stats.speed*0.95;
   const res=resolveMove(player.pos.x,player.pos.z,dx*spd*dt,dz*spd*dt,0.35,world.bounds,world.obstacles);
   player.pos.set(res.x,0,res.z);
   const targetAngle=Math.atan2(dx,dz);
   player.facing=lerpAngle(player.facing,targetAngle,1-Math.exp(-dt*12));
   moving=move.magnitude;
 }
}
app.hero.position.copy(player.pos); app.hero.rotation.y=player.facing;
animateHero(app.hero,time,{moving:moving*0.9,attack:-1});
updateFollowCamera(dt,player.pos,{y:7.8,z:9.6,lookY:1.05});
// near interactable
const near=world.interactables.find(i=>dist(player.pos,i)<i.range);
if(near && !overlay) ui.showInteract(near.label); else ui.hideInteract();
app.lobbyNear=near;
```
- Need if overlay open and near, hide prompt.
