537:   drawMinimap(playerPos, enemies, bounds = 21) {
538:     const canvas = $('minimap');
539:     if (!canvas) return;
540:     const ctx = canvas.getContext('2d');
541:     const w = canvas.width;
542:     const h = canvas.height;
543:     ctx.clearRect(0, 0, w, h);
544:     const cx = w / 2;
545:     const cy = h / 2;
546:     const scale = (w * 0.42) / bounds;
547:     // rings
548:     ctx.strokeStyle = 'rgba(231,196,119,0.22)';
549:     ctx.lineWidth = 1;
550:     for (const r of [6, 12, 18]) {
551:       ctx.beginPath();
552:       ctx.arc(cx, cy, r * scale, 0, Math.PI * 2);
553:       ctx.stroke();
554:     }
555:     // enemy dots
556:     for (const e of enemies) {
557:       if (!e.alive) continue;
558:       const x = cx + e.mesh.position.x * scale;
