519: function makeGlowTexture(color) {
520:   const canvas = document.createElement('canvas');
521:   canvas.width = 128;
522:   canvas.height = 128;
523:   const ctx = canvas.getContext('2d');
524:   const grad = ctx.createRadialGradient(64, 64, 2, 64, 64, 64);
525:   grad.addColorStop(0, color);
526:   grad.addColorStop(0.25, color);
527:   grad.addColorStop(1, 'rgba(0,0,0,0)');
528:   ctx.fillStyle = grad;
529:   ctx.fillRect(0, 0, 128, 128);
530:   const tex = new THREE.CanvasTexture(canvas);
531:   tex.colorSpace = THREE.SRGBColorSpace;
532:   return tex;
533: }
