915:   const moving = Math.max(0, Math.min(1, opts.moving || 0));
916:   const attack = opts.attack ?? -1;
917:   const dead = opts.dead || false;
918:   const walk = Math.sin(t * 8.5 + (d.phase || 0)) * 0.55 * moving;
919: 
920:   if (d.floating) {
921:     enemy.position.y = (d.baseY || 0) + Math.sin(t * 2 + (d.phase || 0)) * 0.12;
922:     if (d.body) d.body.rotation.z = Math.sin(t * 1.2) * 0.06;
923:   }
924: 
925:   if (d.legL) d.legL.rotation.x = walk;
926:   if (d.legR) d.legR.rotation.x = -walk;
927:   if (d.legs) {
928:     d.legs.forEach((leg, i) => {
929:       leg.rotation.x = (i % 2 === 0 ? 1 : -1) * walk;
930:     });
931:     if (d.tail) d.tail.rotation.y = Math.sin(t * 5) * 0.4;
932:   }
933:   if (d.armL) d.armL.rotation.x = d.armL.rotation.x * 0.8 + (moving ? -walk * 0.3 : 0);
934:   if (d.armR) d.armR.rotation.x = d.armR.rotation.x * 0.8 + (moving ? walk * 0.3 : 0);
935:   if (d.head) {
936:     d.head.rotation.y = Math.sin(t * 0.9 + (d.phase || 0)) * 0.08;
937:   }
938:   if (d.torso) d.torso.rotation.z = Math.sin(t * 1.7) * 0.025;
939:   if (d.body && !d.floating) d.body.position.y = 0.62 + Math.abs(Math.sin(t * 8.5)) * 0.03 * moving;
