input.content:
import * as THREE from 'three';
import { CLASSES, MAPS } from './data.js';
import { createDog, createHero, createVendor } from './models.js';
import { buildMapDiorama } from './worlds.js';

function rgba(hex, alpha) {
  const c = new THREE.Color(hex);
  return `rgba(${Math.round(c.r * 255)},${Math.round(c.g * 255)},${Math.round(c.b * 255)},${alpha})`;
}

function makeBackdrop(color, w, h, warm = false) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  const base = ctx.createLinearGradient(0, 0, 0, h);
  base.addColorStop(0, warm ? '#21140d' : '#0b111d');
  base.addColorStop(0.55, warm ? '#17100c' : '#0c111a');
  base.addColorStop(1, warm ? '#0a0705' : '#070a11');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, w, h);

  const glow = ctx.createRadialGradient(w * 0.5, h * 0.32, 2, w * 0.5, h * 0.32, w * 0.62);
  glow.addColorStop(0, rgba(color, warm ? 0.5 : 0.4));
  glow.addColorStop(0.45, rgba(color, 0.14));
  glow.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);

  const floor = ctx.createRadialGradient(w * 0.5, h * 0.92, 2, w * 0.5, h * 0.92, w * 0.52);
  floor.addColorStop(0, rgba(color, 0.26));
  floor.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = floor;
  ctx.fillRect(0, 0, w, h);

  // subtle vignette
  const vignette = ctx.createRadialGradient(w * 0.5, h * 0.45, w * 0.2, w * 0.5, h * 0.45, w * 0.75);
  vignette.addColorStop(0, 'rgba(0,0,0,0)');
  vignette.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, w, h);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

export function generateArt() {
  const portraits = { classes: {}, vendor: null };
  const thumbs = {};
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, preserveDrawingBuffer: true });
  } catch {
    return { portraits, thumbs };
  }
  renderer.setPixelRatio(1);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.08;

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(34, 320 / 420, 0.1, 40);
  camera.position.set(0.14, 1.26, 3.55);
  camera.lookAt(0, 1.04, 0);

  const hemi = new THREE.HemisphereLight(0xbfd0ee, 0x1a1410, 1.35);
  scene.add(hemi);
  const key = new THREE.DirectionalLight(0xffe0b0, 2.6);
  key.position.set(2.4, 4.2, 3.2);
  key.castShadow = true;
  key.shadow.mapSize.set(512, 512);
  key.shadow.camera.left = -2.5;
  key.shadow.camera.right = 2.5;
  key.shadow.camera.top = 3;
  key.shadow.camera.bottom = -1;
  key.shadow.camera.near = 0.5;
  key.shadow.camera.far = 12;
  key.shadow.bias = -0.001;
  scene.add(key);
  const fill = new THREE.PointLight(0x6ea8e8, 3.2, 9, 2);
  fill.position.set(-2.4, 2.2, 2.2);
  scene.add(fill);
  const rim = new THREE.PointLight(0xc08cff, 2.6, 8, 2);
  rim.position.set(1.6, 2.6, -2.6);
  scene.add(rim);

  const floor = new THREE.Mesh(
    new THREE.CircleGeometry(2.4, 40),
    new THREE.MeshStandardMaterial({ color: '#171b24', roughness: 0.95, metalness: 0.05 })
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.015;
  floor.receiveShadow = true;
  scene.add(floor);
  const floorRing = new THREE.Mesh(
    new THREE.RingGeometry(1.35, 1.43, 48),
    new THREE.MeshBasicMaterial({ color: '#6ea8e8', transparent: true, opacity: 0.4, side: THREE.DoubleSide, depthWrite: false })
  );
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.005;
  scene.add(floorRing);

  let currentHero = null;
  const clearHero = () => {
    if (currentHero) {
      scene.remove(currentHero);
      currentHero = null;
    }
  };

  try {
    renderer.setSize(320, 420, false);
    camera.aspect = 320 / 420;
    camera.updateProjectionMatrix();
    for (const c of CLASSES) {
      scene.background = makeBackdrop(c.color, 320, 420);
      key.color.set(c.color);
      fill.color.set(c.color);
      rim.color.set(c.color);
      floorRing.material.color.set(c.color);
      clearHero();
      currentHero = createHero(c.id);
      currentHero.position.set(0, 0, 0);
      currentHero.rotation.y = 0.06;
      scene.add(currentHero);
      renderer.render(scene, camera);
      portraits.classes[c.id] = renderer.domElement.toDataURL('image/jpeg', 0.9);
    }

    // Maelis and Brasa portrait
    clearHero();
    scene.background = makeBackdrop('#d2a84e', 320, 320, true);
    key.color.set('#ffcf8a');
    fill.color.set('#ff9a4a');
    rim.color.set('#e8c477');
    floorRing.material.color.set('#d2a84e');
    camera.aspect = 1;
    camera.position.set(0.25, 1.32, 4.05);
    camera.lookAt(0, 1.02, 0);
    camera.updateProjectionMatrix();
    renderer.setSize(320, 320, false);
    const vendor = createVendor();
    vendor.position.set(-0.52, 0, 0);
    vendor.rotation.y = 0.05;
    scene.add(vendor);
    const dog = createDog();
    dog.position.set(0.78, 0, 0.22);
    dog.rotation.y = -0.62;
    scene.add(dog);
    renderer.render(scene, camera);
    portraits.vendor = renderer.domElement.toDataURL('image/jpeg', 0.9);
    scene.remove(vendor);
    scene.remove(dog);

    // Map dioramas
    renderer.setSize(480, 300, false);
    for (const map of MAPS) {
      const diorama = buildMapDiorama(map.id);
      diorama.camera.aspect = 480 / 300;
      diorama.camera.updateProjectionMatrix();
      renderer.render(diorama.scene, diorama.camera);
      thumbs[map.id] = renderer.domElement.toDataURL('image/jpeg', 0.88);
    }
  } catch (err) {
    console.warn('Falha ao gerar arte procedural', err);
  } finally {
    try {
      renderer.dispose();
      renderer.forceContextLoss();
    } catch {
      /* ignore */
    }
  }

  return { portraits, thumbs };
}

content.text:
Now main.js. Need be careful with DOM IDs. Let's write in sections maybe 500 lines. We'll use write then check.

Detailed main.js:

```js
import * as THREE from 'three';
import { CLASSES, CLASS_BY_ID, ITEM_BY_ID } from './data.js';
import { buyItem, computeStats, equipItem, loadProfile, saveProfile, xpProgress } from './profile.js';
import { buildAdventureWorld, buildLobbyWorld, buildShowcaseWorld, buildTitleWorld } from './worlds.js';
import { animateHero, createHero } from './models.js';
import { GameUI } from './ui.js';
import { Input } from './input.js';
import { AudioEngine } from './audio.js';
import { FX } from './fx.js';
import { Adventure } from './combat.js';
import { generateArt } from './art.js';
```

Boot.

Renderer:
```
const canvas = document.getElementById('game-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference:'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio||1, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.outputColorSpace = THREE.SRGBColorSpace;
```
Three r187 default outputColorSpace SRGB. Fine.

Hit flash:
```
const hitFlash = document.createElement('div'); hitFlash.id='hit-flash'; document.getElementById('app').appendChild(hitFlash);
let hitTimer=0;
function flashHit(){ hitFlash.animate([{opacity:0.85},{opacity:0}],{duration:260,easing:'ease-out'}); }
```
CSS #hit-flash exists. Using Web Animations.

State variables:
```
let state='boot', world=null, titleWorld=null, showcaseWorld=null, showcaseHero=null, lobbyWorld=null, lobbyPlayer=null, adventure=null, currentMapId=null, paused=false, modalOpen=false, helpOpen=false, resultOpen=false;
const lobby = { player:null, nearest:null };
```

Input:
```
const input = new Input();
const audio = new AudioEngine();
const ui = new GameUI();
const profile = loadProfile();
ui.setProfile(profile);
```
Audio init on first pointerdown:
```
const unlockAudio = ()=>{ audio.init(); audio.setMood(state==='adventure' ? (adventure?.boss?'boss':'adventure') : state==='lobby'?'lobby':state==='select'?'title':'title'); window.removeEventListener('pointerdown',unlockAudio); };
window.addEventListener('pointerdown', unlockAudio, {once:true});
```
But `once:true` plus remove fine. Keyboard-only user won't init; add keydown too? Could add window keydown once. Not necessary but nice:
```
window.addEventListener('keydown', unlockAudio, {once:true});
```
But removing pointerdown then keydown still triggers audio.init twice; AudioEngine.init checks ctx. fine.

Input handlers:
```
input.on('uiClick', ()=>{ audio.init(); audio.play('ui'); });
input.on('attack', ()=>{ if(state==='adventure' && adventure && !paused && !modalOpen) adventure.queueAttack(); });
input.on('ability', i=>{ if(...) adventure.useAbility(i); });
input.on('dodge', ()=>{...});
input.on('potion', kind=>{...});
input.on('pause', ()=> { if(state==='adventure') togglePause(); else if(modalOpen) closeAnyModal(); });
input.on('lobby', ()=> { if(state==='adventure' && adventure) adventure.exitToLobby(); });
```
But uiClick fires on every button pointerdown, including ability buttons? `document.querySelectorAll('.ability-btn')` not in list of .btn etc. Attack button? not. Good. But `input.bindButtons` attaches uiClick to `.btn`, `.icon-btn`, etc. Ability button has own. Fine.

Potential issue: clicking canvas for lobby interaction also triggers global unlock only.

UI handlers:
```
Object.assign(ui.handlers, {...});
```
Need callbacks.

`onStart`: audio.init; audio.setMood('title'); enterSelect();
`onBackTitle`: state='title'; ui.showTitle(); setActiveWorld(titleWorld); audio.setMood('title'); paused=false; modalOpen=false; input.enabled=true;
`onSelectClass`: selectClass(id);
`onConfirmClass`: profile.selectedClass=ui.selectedClassId; saveProfile; enterLobby();
`onOpenShop`: openShop();
`onOpenMaps`: openMaps();
`onCloseModal`: closeModal(id);
`onEnterMap`: startAdventure(id);
`onLobby`: if adventure adventure.exitToLobby(); else if state==='adventure' enterLobby();
`onPause`: togglePause();
`onResume`: resume();
`onPauseLobby`: if adventure adventure.exitToLobby(); else enterLobby();
`onRetry`: retryMap();
`onResultLobby`: if adventure adventure.exitToLobby(); else enterLobby();
`onOpenHelp`: openHelp();
`onCloseHelp`: closeHelp();
`onBuy`: buy(id);
`onEquip`: equip(id);
`onSound`: toggleSound();
```

Important: `onResultLobby` calls adventure.exitToLobby. If finished true, dispose and onExit -> enterLobby. Good.

`enterSelect`:
- state='select'; setActiveWorld(showcaseWorld); ui.showSelect(); selectClass(profile.selectedClass); audio.setMood('title'); input.enabled=true; paused=false; modalOpen=false.
- `selectClass` calls ui.updateSelectPanel, setShowcaseClass, saveProfile.
- Ensure showcaseWorld built at boot. If not built, build now.

`setShowcaseClass`:
```
if (showcaseHero) { showcaseWorld.scene.remove(showcaseHero); showcaseHero=null; }
showcaseHero = createHero(id);
showcaseHero.position.set(0,0.4,0);
showcaseHero.rotation.y = -0.06;
showcaseWorld.scene.add(showcaseHero);
showcaseWorld.setClass(id);
```
`showcaseWorld` built at boot.

`enterLobby`:
- `ui.hideResult(); ui.closePause(); ui.closeHelp();`
- if (!lobbyWorld) lobbyWorld=buildLobbyWorld();
- if (lobby.player) lobbyWorld.scene.remove(lobby.player.mesh)
- setActiveWorld(lobbyWorld)
- lobby.player = makePlayer(profile.selectedClass, lobbyWorld.playerStart.clone(), Math.PI)
- position camera immediately `updateLobbyCamera(0, true)`.
- state='lobby'; paused=false; modalOpen=false; input.enabled=true; adventure=null? If coming from adventure, adventure already disposed. Set adventure=null.
- ui.showLobby(profile); ui.setSoundIcon(audio.muted); ui.hideInteract(); audio.setMood('lobby'); ui.setupAbilities? no.
- maybe toast if just exited adventure with xp; handle separately.
- `ui.toast` welcome maybe only first time? Could toast class name. Fine: `ui.toast(`${class.name}, ${class.title}`, '✦')`. But could be noisy. Let's do once per entry maybe okay.

`makePlayer(classId, position, facing)`:
```
const stats = computeStats(profile,classId);
const mesh=createHero(classId);
mesh.position.copy(position); mesh.rotation.y=facing;
world.scene.add(mesh);
return {classId, mesh, stats, hp:stats.maxHp, mana:stats.maxMana, facing, attackTimer:0, attackAnim:-1, abilityAnim:-1, abilityCooldowns:[0,0,0], dodgeCooldown:0, dodgeTimer:0, dodgeDir:{x:0,z:1}, invuln:0, buffs:[], dodgeRatio:0};
```
Careful: `world` global set before makePlayer. In enterLobby setActiveWorld first then makePlayer. In startAdventure same. Good.

`startAdventure(mapId)`:
```
if (adventure) { adventure.dispose(); adventure=null; }
const w = buildAdventureWorld(mapId);
currentMapId=mapId;
setActiveWorld(w);
const p = makePlayer(profile.selectedClass, w.playerStart.clone(), Math.PI);
const fx = new FX(w.scene);
ui.showAdventure(profile);
ui.setupAbilities(CLASS_BY_ID[profile.selectedClass]);
ui.hideBoss(); ui.clearEnemyBars(); ui.updateBuffs([]);
ui.hideResult(); ui.closePause(); ui.closeHelp();
adventure = new Adventure({world:w, player:p, profile, ui, audio, input, camera:w.camera, fx, onExit: handleAdventureExit, onPlayerHit: flashHit, onFinished: handleAdventureFinished});
adventure.start();
state='adventure'; paused=false; modalOpen=false; resultOpen=false; input.enabled=true; audio.init(); audio.setMood('adventure');
```
`w.playerStart` is Vector3; clone.

`handleAdventureExit`:
```
adventure=null; enterLobby();
```
But enterLobby sets adventure=null. Fine. `ui.toast('Sua jornada foi preservada', '✦')` maybe. Could pass xp info. Keep generic.

`handleAdventureFinished(victory)`: `resultOpen=true; input.enabled=false; modalOpen=true;` (result modal). Note adventure still exists; result buttons call exit/retry.
- `input.enabled=false` means joystick no movement. Good.
- But `modalOpen=true` might affect pause; fine.

`togglePause`:
```
if (state!=='adventure' || !adventure || adventure.finished) return;
if (paused) resume(); else { paused=true; input.enabled=false; ui.openPause(); audio.play('ui'); }
```
`resume`: paused=false; ui.closePause(); input.enabled=true; modalOpen=false.
- Don't set modalOpen for pause? We can set true. But if modalOpen true, adventure update still runs because main checks paused; okay. `openHelp` from pause uses paused. Fine.

`openShop`:
```
if (state!=='lobby') return;
modalOpen=true; input.enabled=false; ui.hideInteract(); ui.openShop(profile); audio.play('ui');
```
`openMaps` similar with ui.openMaps(profile).

`closeModal(id)`:
```
ui.closeModal(id + '-modal');
modalOpen=false; input.enabled = state==='lobby' || (state==='adventure' && !paused && !resultOpen);
audio.play('ui');
```
`closeAnyModal` for Escape:
```
if (helpOpen) closeHelp();
else if (modalOpen) {
 if (document.getElementById('shop-modal') && !classList.contains('hidden')) closeModal('shop') ...
 else if maps...
}
```
Maybe simpler: Escape in lobby closes shop/maps. In adventure pause handled by input 'pause'. If help open, close. We'll implement.

`buy(id)`:
```
const item=ITEM_BY_ID[id]; const res=buyItem(profile,item,profile.selectedClass);
if(res.ok){ audio.play('buy'); ui.toast(`${item.name} adquirido`, '◆'); ui.renderShop(); ui.updateProfileUI(profile); }
else { audio.play('error'); toast reason }
