143: function collide(pos, obstacles, radius, bounds) {
144:   const limit = bounds - radius;
145:   pos.x = clamp(pos.x, -limit, limit);
146:   pos.z = clamp(pos.z, -limit, limit);
147:   for (const o of obstacles) {
148:     const dx = pos.x - o.x;
149:     const dz = pos.z - o.z;
150:     const min = (o.r || 0) + radius;
151:     const d = Math.hypot(dx, dz);
152:     if (d < min && d > 0.0001) {
153:       const push = (min - d) / d;
154:       pos.x += dx * push;
155:       pos.z += dz * push;
156:     }
157:   }
158:   pos.x = clamp(pos.x, -limit, limit);
159:   pos.z = clamp(pos.z, -limit, limit);
160: }
