556: function updateLobby(dt, t) {
557:   if (!lobbyPlayer || !lobbyWorld) return;
558:   const p = lobbyPlayer;
559:   const canMove = !modalOpen && !helpOpen;
560:   const move = canMove ? input.getMove() : { x: 0, y: 0, magnitude: 0 };
561:   let moving = 0;
562:   if (move.magnitude > 0.08) {
563:     const speed = p.stats.speed * 1.35;
564:     p.mesh.position.x += move.x * speed * dt;
565:     p.mesh.position.z += move.y * speed * dt;
566:     collide(p.mesh.position, lobbyWorld.obstacles, 0.46, lobbyWorld.bounds);
567:     p.facing = Math.atan2(move.x, move.y);
568:     p.mesh.rotation.y = p.facing;
569:     moving = move.magnitude;
570:   }
571:   animateHero(p.mesh, t, { moving });
572: 
573:   let nearest = null;
574:   let nearestD = Infinity;
575:   for (const it of lobbyWorld.interactables) {
576:     const d = Math.hypot(p.mesh.position.x - it.x, p.mesh.position.z - it.z);
577:     if (d <= it.range && d < nearestD) {
578:       nearest = it;
579:       nearestD = d;
580:     }
581:   }
582:   lobbyNearest = nearest;
