586:   const cam = lobbyWorld.camera;
587:   cameraTarget.set(p.mesh.position.x, 9.2, p.mesh.position.z + 8.4);
588:   cam.position.lerp(cameraTarget, 1 - Math.exp(-dt * 4.2));
