import { chromium } from 'playwright-core';
import fs from 'node:fs';

const exe = '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({
  executablePath: exe,
  args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'],
});

const errors = [];

async function run(label, width, height) {
  const ctx = await browser.newContext({
    viewport: { width, height },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36',
  });
  const page = await ctx.newPage();
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`[${label}] console: ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[${label}] pageerror: ${e.message}`));

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForSelector('#title-screen:not(.hidden)', { timeout: 30000 });
  await page.waitForTimeout(900);

  const overflow = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    scrollH: document.documentElement.scrollHeight,
    innerW: innerWidth,
    innerH: innerHeight,
    bodyOverflow: getComputedStyle(document.body).overflow,
  }));
  console.log(label, 'overflow', JSON.stringify(overflow));
  await page.screenshot({ path: `${OUT}/${label}-01-title.png` });

  await page.click('#btn-start');
  await page.waitForSelector('#select-screen:not(.hidden)');
  await page.waitForTimeout(900);
  const cardBox = await page.locator('.class-card').first().boundingBox();
  const confirmBox = await page.locator('#btn-confirm-class').boundingBox();
  console.log(label, 'select card', JSON.stringify(cardBox), 'confirm', JSON.stringify(confirmBox));
  await page.screenshot({ path: `${OUT}/${label}-02-select.png` });

  // select whip class
  await page.click('.class-card[data-class="whipdancer"]');
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/${label}-03-select-whip.png` });
  await page.click('#btn-confirm-class');
  await page.waitForSelector('#lobby-ui:not(.hidden)');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${OUT}/${label}-04-lobby.png` });

  // shop
  await page.click('#btn-shop');
  await page.waitForSelector('#shop-modal:not(.hidden)');
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/${label}-05-shop.png` });
  const shopScroll = await page.evaluate(() => {
    const el = document.querySelector('.shop-items');
    return el ? { h: el.scrollHeight, c: el.clientHeight, w: el.scrollWidth, cw: el.clientWidth } : null;
  });
  console.log(label, 'shop-scroll', JSON.stringify(shopScroll));
  await page.click('#btn-shop-close');
  await page.waitForTimeout(300);

  // maps
  await page.click('#btn-maps');
  await page.waitForSelector('#maps-modal:not(.hidden)');
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/${label}-06-maps.png` });
  await page.click('#btn-maps-close');
  await page.waitForTimeout(300);

  // adventure
  await page.click('#btn-maps');
  await page.waitForSelector('#maps-modal:not(.hidden)');
  await page.click('.map-card[data-map="crypt"]');
  await page.waitForSelector('#adventure-hud:not(.hidden)');
  await page.waitForTimeout(1600);
  await page.screenshot({ path: `${OUT}/${label}-07-adventure.png` });
  const hud = await page.evaluate(() => {
    const ids = ['combat-joystick', 'btn-attack', 'btn-potion', 'btn-dodge', 'btn-lobby', 'btn-pause', 'minimap'];
    const out = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el) { out[id] = null; continue; }
      const r = el.getBoundingClientRect();
      out[id] = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), visible: r.width > 0 && r.height > 0 };
    }
    return out;
  });
  console.log(label, 'hud', JSON.stringify(hud));

  await ctx.close();
}

await run('portrait', 390, 844);
await run('landscape', 844, 390);

console.log('ERRORS:', errors.length ? '\n' + errors.join('\n') : 'none');
await browser.close();

